using Fonlow.ErpNext.Abstract;
using System.Text.Json.Serialization;

namespace Fonlow.ErpNext.DocTypes
{
    public class DocTypeArrayResponse<DataT>
    {
        [JsonPropertyName("data")]
        public DataT[] Data { get; set; }
    }

    public class DocTypeResponse<DataT> 
    {
        [JsonPropertyName("data")]
        public DataT Data { get; set; }
    }

    /// <summary>
    /// Common base type of many DocType
    /// </summary>
    public class DocTypeBase
    {
        /// <summary>
        /// Name is actually ID, generated by ERPNext according to name series template, though by default, use something like customer name when importing, or DotAlias+Timestamp.
        /// </summary>
        [JsonPropertyName("name")]
        public string Name { get; set; }

        [JsonPropertyName("doctype")]
        public string DocType => DocTypeName.Get(GetType());
        /// <summary>
        /// User tags for various purpose, when having ?expand_links=True
        /// </summary>
        [JsonPropertyName("_user_tags")]
        public string UserTags { get; set; }
    }

    public class DocTypeWithLinks : DocTypeBase
    {
        [JsonPropertyName("links")]
        public Link[] Links { get; set; }
    }

    public class Link
    {
        [JsonPropertyName("link_doctype")]
        public string LinkDocType { get; set; }

        [JsonPropertyName("link_name")]
        public string LinkName { get; set; }

        /// <summary>
        /// For example, customer's customerName
        /// </summary>
        [JsonPropertyName("link_title")]
        public string LinkTitle { get; set; }
    }

    public class PhoneLink
    {
        [JsonPropertyName("phone")]
        public string Phone { get; set; }

        [JsonPropertyName("is_primary_phone")]
        public int IsPrimary { get; set; }

        [JsonPropertyName("is_primary_mobile_no")]
        public int IsPrimaryMobile { get; set; }
    }

    public class EmailLink
    {
        [JsonPropertyName("email_id")]
        public string EmailId { get; set; }

        [JsonPropertyName("is_primary")]
        public int IsPrimary { get; set; }
    }

    public class MessageResponse
    {
        [JsonPropertyName("message")]
        public string Message { get; set; }
    }

    public class NumberMessageResponse
    {
        [JsonPropertyName("message")]
        public int Message { get; set; }
    }

    public class DataStringResponse
    {
        [JsonPropertyName("data")]
        public string Data { get; set; }
    }




}
